existing('t5',11,1,20)
add('pt21',11,'整个 epoch 的 MSE',2,'实现',
 '一轮损失应将所有误差平方合并后除以总元素数。先算每批mean再等权平均，在尾批较小时会产生偏差。评估时还要关闭梯度并临时进入eval。',
 'errors=[torch.tensor([1.,1.,1.]),torch.tensor([9.])]\nprint(sum(e.sum() for e in errors)/sum(e.numel() for e in errors))',
 ['保存模型模式，并在eval、no_grad中遍历(x,y)批次。','累计平方误差sum与目标元素数，而不是batch数量。','无数据返回0.0；finally恢复原模式。返回Python浮点。'],
 '定义 epoch_mse(model,batches)，按全体目标元素计算整体MSE，空批次集合返回0，保持模型原模式。','def epoch_mse(model, batches)',
 'def epoch_mse(model,batches):\n    mode=model.training\n    model.eval()\n    total=0.0\n    count=0\n    try:\n        with torch.no_grad():\n            for x,y in batches:\n                total+=((model(x)-y)**2).sum().item()\n                count+=y.numel()\n        return total/count if count else 0.0\n    finally:\n        model.train(mode)',
 [case('epoch_mse(torch.nn.Identity(),[(torch.zeros(3),torch.ones(3)),(torch.zeros(1),torch.tensor([3.]))])',3,label='尾批加权'),case('epoch_mse(torch.nn.Identity(),[])',0,label='空epoch'),case('m.training',True,setup='m=torch.nn.Identity()\nepoch_mse(m,[])',label='模式恢复'),case('epoch_mse(torch.nn.Dropout(1),[(torch.ones(2),torch.ones(2))])',0,label='eval行为')],
 quiz('每批MSE分别为1和9，批次大小3和1，整体MSE是多少？',['5','3','10'],1,['这忽略了批次权重。','对，(3×1+1×9)/4=3。','那是批次均值相加。']),
 examples=[example('尾批权重','print((3*1+1*9)/4)','3.0','按元素数加权。'),example('错误的批次平均','print((1+9)/2)','5.0','这种写法会过度加权尾批。')],minutes=25)
add('pt22',11,'二分类指标的零分母',2,'实现',
 '准确率不能覆盖所有分类表现。以1为正类，precision=TP/(TP+FP)，recall=TP/(TP+FN)，F1=2TP/(2TP+FP+FN)。本题约定零分母时返回0。',
 'pred=torch.tensor([1,1,0])\ny=torch.tensor([1,0,1])\nprint(((pred==1)&(y==1)).sum())',
 ['输入logits用>=0映射为正类，标签是0或1。','用布尔张量统计TP、FP、FN，转Python数值后计算各指标。','空输入以及没有预测正例时也需要明确输出，不能出现NaN。'],
 '定义 binary_metrics(logits,labels)，一维同长输入，返回precision、recall、f1字典；logit=0预测正类，各零分母指标返回0。','def binary_metrics(logits, labels)',
 'def binary_metrics(logits,labels):\n    pred=logits>=0\n    truth=labels==1\n    tp=(pred&truth).sum().item()\n    fp=(pred&~truth).sum().item()\n    fn=(~pred&truth).sum().item()\n    return {"precision":tp/(tp+fp) if tp+fp else 0.0,"recall":tp/(tp+fn) if tp+fn else 0.0,"f1":2*tp/(2*tp+fp+fn) if 2*tp+fp+fn else 0.0}',
 [case('binary_metrics(torch.tensor([2.,1.,-1.]),torch.tensor([1,0,1]))',{'precision':0.5,'recall':0.5,'f1':0.5},label='混合预测'),case('binary_metrics(torch.tensor([-1.,-2.]),torch.tensor([0,0]))',{'precision':0,'recall':0,'f1':0},label='无正例'),case('binary_metrics(torch.empty(0),torch.empty(0,dtype=torch.long))',{'precision':0,'recall':0,'f1':0},label='空输入'),case('binary_metrics(torch.tensor([0.]),torch.tensor([1]))',{'precision':1,'recall':1,'f1':1},label='零阈值')],
 quiz('没有任何预测正例时，本题precision是多少？',['NaN','0','1'],1,['接口应避免NaN。','对，本题明确约定返回0。','没有证据说明预测正例全部正确。']),
 examples=[example('真阳性','p=torch.tensor([True,True,False]);y=torch.tensor([True,False,True])\nprint((p&y).sum().item())','1','两边都为正的才是TP。'),example('F1直接计数','tp,fp,fn=2,1,3\nprint(2*tp/(2*tp+fp+fn))','0.5','直接用计数可以少一层零分母问题。')],minutes=25)
add('pt23',11,'完整的分类评估循环',3,'综合',
 '评估循环需要同时管住模式、梯度与指标聚合。CrossEntropyLoss接收logits与long标签；sum reduction便于按全部样本计算平均，而非等权平均每批结果。',
 'logits=torch.tensor([[2.,0.],[0.,2.]])\ny=torch.tensor([0,1])\nprint(logits.argmax(1)==y)',
 ['在eval与no_grad下迭代(x,y)，求交叉熵sum、预测正确数与样本数。','最终loss=sum_loss/count，accuracy=correct/count，空集两项为0。','finally恢复原模式；不能更新参数或生成验证输入梯度。'],
 '定义 evaluate_classifier(model,batches)，返回 {loss,accuracy}，遵守全部评估规则。','def evaluate_classifier(model, batches)',
 'def evaluate_classifier(model,batches):\n    mode=model.training\n    model.eval()\n    loss_sum=0.0\n    correct=0\n    count=0\n    try:\n        with torch.no_grad():\n            for x,y in batches:\n                logits=model(x)\n                loss_sum+=torch.nn.functional.cross_entropy(logits,y,reduction="sum").item()\n                correct+=(logits.argmax(1)==y).sum().item()\n                count+=len(y)\n        return {"loss":loss_sum/count if count else 0.0,"accuracy":correct/count if count else 0.0}\n    finally:\n        model.train(mode)',
 [case('evaluate_classifier(torch.nn.Identity(),[(torch.zeros(3,2),torch.tensor([0,0,0])),(torch.zeros(1,2),torch.tensor([1]))])',{'loss':0.69314718,'accuracy':0.75},label='尾批正确聚合'),case('evaluate_classifier(torch.nn.Identity(),[])',{'loss':0,'accuracy':0},label='空数据'),case('m.training',True,setup='m=torch.nn.Linear(2,2)\nevaluate_classifier(m,[])',label='恢复模式'),case('x.grad is None',True,setup='m=torch.nn.Linear(2,2)\nx=torch.ones(2,2,requires_grad=True)\nevaluate_classifier(m,[(x,torch.tensor([0,1]))])',label='验证不反向')],
 quiz('用reduction="sum"后最后除以什么？',['批次数','全部样本数','类别数量'],1,['尾批大小可能不同。','对，每条样本相同权重。','类别数不是平均的分母。']),
 examples=[example('类别选择','print(torch.tensor([[1.,3.],[5.,2.]]).argmax(1))','tensor([1, 0])','每条样本单独选择最高logit。'),example('无数据的约定','count=0\nprint(0.0 if count==0 else 1/count)','0.0','空验证集不能触发零除。')],minutes=35)
add('pt24',11,'保存的是状态，不是引用',3,'实现',
 'checkpoint通常包含模型参数、优化器状态和epoch。state_dict描述这些数值。保存后若继续训练，最佳状态的内存副本必须深复制；磁盘checkpoint则在保存时写入数值快照。',
 'import copy\nm=torch.nn.Linear(2,1)\nsnapshot=copy.deepcopy(m.state_dict())\nprint(sorted(snapshot.keys()))',
 ['save_checkpoint(model,optimizer,epoch,path) 用torch.save保存model、optimizer、epoch三个键。','load_checkpoint按CPU、weights_only=True加载，再恢复两个state_dict，返回epoch。','测试会在保存后修改参数，再加载检查是否恢复。返回epoch而不是下一轮编号。'],
 '定义 save_checkpoint(model,optimizer,epoch,path) 与 load_checkpoint(model,optimizer,path)。按上述三个键保存并恢复；load返回epoch。','save_checkpoint / load_checkpoint',
 'def save_checkpoint(model,optimizer,epoch,path):\n    torch.save({"model":model.state_dict(),"optimizer":optimizer.state_dict(),"epoch":epoch},path)\ndef load_checkpoint(model,optimizer,path):\n    state=torch.load(path,map_location="cpu",weights_only=True)\n    model.load_state_dict(state["model"])\n    optimizer.load_state_dict(state["optimizer"])\n    return state["epoch"]',
 [case('epoch',7,setup='m=torch.nn.Linear(2,1)\no=torch.optim.SGD(m.parameters(),lr=0.2)\nsave_checkpoint(m,o,7,"state.pt")\nepoch=load_checkpoint(m,o,"state.pt")',label='恢复epoch'),case('torch.allclose(m.weight,old)',True,setup='m=torch.nn.Linear(2,1)\no=torch.optim.SGD(m.parameters(),lr=0.2)\nold=m.weight.detach().clone()\nsave_checkpoint(m,o,3,"state.pt")\nwith torch.no_grad():\n    m.weight.add_(9)\nload_checkpoint(m,o,"state.pt")',label='参数恢复'),case('o.param_groups[0]["lr"]',0.2,setup='m=torch.nn.Linear(2,1)\no=torch.optim.SGD(m.parameters(),lr=0.2)\nsave_checkpoint(m,o,1,"state.pt")\no.param_groups[0]["lr"]=9\nload_checkpoint(m,o,"state.pt")',label='优化器状态恢复')],
 quiz('best=model.state_dict() 后继续训练，为什么可能丢失原最佳值？',['state_dict是完全独立的快照','内部张量仍可能共享参数存储，需要deepcopy','state_dict不能保存到磁盘'],1,['仅赋值不会深复制。','对，保存内存中的最佳状态时尤其要注意。','torch.save可以保存它。']),
 examples=[example('状态键','m=torch.nn.Linear(2,1)\nprint(sorted(m.state_dict().keys()))',"['bias', 'weight']",'state_dict以名称对应参数或buffer。'),example('独立快照','import copy\nm=torch.nn.Linear(1,1)\ns=copy.deepcopy(m.state_dict())\nprint(s["weight"].data_ptr()!=m.weight.data_ptr())','True','内存快照需要独立存储。')],minutes=30)
add('pt25',11,'写一个可复用的分类训练步骤',2,'排错',
 '训练步骤应该能重复调用而不累积上一轮梯度。先train、zero_grad，再前向、交叉熵、backward和step。返回Python损失值用于记录，但不能在反向前用item替代张量loss。',
 'optimizer.zero_grad()\nloss=torch.nn.functional.cross_entropy(model(x),labels)\nloss.backward()\noptimizer.step()',
 ['设置model.train()，再optimizer.zero_grad。','使用原始logits与long标签计算交叉熵，调用backward和step。','最后返回loss.item()；旧梯度可能预先存在，测试会检查清空行为。'],
 '定义 train_step(model,optimizer,x,labels)，完成一个分类训练步骤并返回Python loss。','def train_step(model, optimizer, x, labels)',
 'def train_step(model,optimizer,x,labels):\n    model.train()\n    optimizer.zero_grad()\n    loss=torch.nn.functional.cross_entropy(model(x),labels)\n    loss.backward()\n    optimizer.step()\n    return loss.item()',
 [case('loss',0.69314718,setup='m=torch.nn.Linear(1,2,bias=False)\ntorch.nn.init.zeros_(m.weight)\no=torch.optim.SGD(m.parameters(),lr=0.1)\nloss=train_step(m,o,torch.ones(1,1),torch.tensor([0]))',label='初始损失'),case('m.weight',[ [0.05],[-0.05] ],setup='m=torch.nn.Linear(1,2,bias=False)\ntorch.nn.init.zeros_(m.weight)\nm.weight.grad=torch.ones_like(m.weight)*100\no=torch.optim.SGD(m.parameters(),lr=0.1)\ntrain_step(m,o,torch.ones(1,1),torch.tensor([0]))',label='清空旧梯度'),case('m.training',True,setup='m=torch.nn.Linear(1,2)\nm.eval()\no=torch.optim.SGD(m.parameters(),lr=0.1)\ntrain_step(m,o,torch.ones(1,1),torch.tensor([0]))',label='切回train')],
 quiz('loss.item() 应该放在哪里？',['backward前替换loss','反向传播之后，用于返回或记录','永远不能用'],1,['Python数值不携带计算图。','对，记录数值和训练用的loss分开。','item是常用记录方法。']),
 bug='loss=torch.nn.functional.cross_entropy(model(x),labels).item()\nloss.backward()',
 examples=[example('数值与张量','x=torch.tensor(2.,requires_grad=True)\nprint(type(x.item()).__name__)','float','转成Python数值后无法对其backward。'),example('训练模式','m=torch.nn.Linear(1,2)\nm.eval()\nm.train()\nprint(m.training)','True','训练步骤应确保处于训练模式。')],minutes=30)
